<template>
  <div class="write_list_box"  v-loading="loading">
    <div class="list_top" @click="return_vote_list_add" v-if="!pigcms_id">
      <i class="el-icon-arrow-left"></i>&nbsp;&nbsp;返回列表
    </div>
    <el-container>
      <el-header>
        <el-row>
          <el-col :span="4" v-if="!pigcms_id">
            <el-button type="primary" icon="el-icon-plus" @click="add_write">填写内容</el-button>
          </el-col>
          <el-col :span="20">
<!--            <span>筛选：</span>-->
<!--            <el-input class="search_width" v-model="search_val" size="small" maxlength="10" placeholder="请输入搜索内容"></el-input>-->
<!--            <el-select class="search_width" v-model="search_type" placeholder="请选择" size="small">-->
<!--              <el-option-->
<!--                v-for="item in options"-->
<!--                :key="item.value"-->
<!--                :label="item.label"-->
<!--                :value="item.value">-->
<!--              </el-option>-->
<!--            </el-select>-->
<!--            &nbsp;&nbsp;&nbsp;&nbsp;-->
            <span>日期筛选：</span>
            <el-date-picker
              size="small"
              v-model="date"
              value-format="yyyy/MM/dd"
              type="daterange"
              range-separator="至"
              start-placeholder="开始日期"
              end-placeholder="结束日期">
            </el-date-picker>
            &nbsp;&nbsp;&nbsp;&nbsp;
            <el-button type="primary" icon="el-icon-search" @click="search_list">查询</el-button>
          </el-col>
        </el-row>

      </el-header>
      <el-main class="table_box" v-if="template_data">
        <el-table
          class="list_table"
          :data="template_data"
          style="width:100%"
          :row-class-name="tableRowClassName"
          :height="650">
          <el-table-column
            prop="id"
            label="ID"
            min-width="40">
          </el-table-column>
          <el-table-column
            prop="title"
            label="模板标题"
            min-width="120">
          </el-table-column>
          <el-table-column
            prop="add_time_txt"
            label="申请填写时间"
            min-width="150">
          </el-table-column>
          <el-table-column
            label="附件"
            min-width="100">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click.native.prevent="lookFile(scope.$index, template_data)">查看附件</el-button>
            </template>
          </el-table-column>
          <el-table-column
            label="备注"
            min-width="100">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click.native.prevent="lookRemark(scope.$index, template_data)">查看备注</el-button>
            </template>
          </el-table-column>
          <el-table-column
            prop="diy_tatus_txt"
            label="状态"
            min-width="50">
            <template slot-scope="scope">
              <el-tag v-if="0==scope.row.diy_tatus" type="warning">{{scope.row.diy_tatus_txt}}</el-tag>
              <el-tag v-if="1==scope.row.diy_tatus" type="success">{{scope.row.diy_tatus_txt}}</el-tag>
              <el-tag v-if="3==scope.row.diy_tatus" type="danger">{{scope.row.diy_tatus_txt}}</el-tag>
            </template>
          </el-table-column>
          <el-table-column
            fixed="right"
            label="操作"
            width="300">
            <template slot-scope="scope">
              <el-button type="text" size="small" @click.native.prevent="editRow(scope.$index, template_data)">编辑</el-button>
              <!-- <el-button type="text" size="small" @click.native.prevent="uploadFile(scope.$index, template_data)">上传附件</el-button> -->
              <el-button
                @click.native.prevent="deleteRow(scope.$index, template_data)"
                type="text"
                class="Danger"
                size="small">
                删除
              </el-button>
            </template>
          </el-table-column>
        </el-table>
      </el-main>

      <el-footer>
        <div v-show="total_page>0" class="page_msg">
          <el-pagination
            background
            layout="prev, pager, next"
            :page-count="total_page"
            :current-page="page"
            @current-change="current_change"
          >
          </el-pagination>
        </div>
      </el-footer>
    </el-container>

    <!-- 弹出层 -->
    <el-dialog title="备注信息" :center="true" :visible.sync="lookRemarkDialog" :close-on-click-modal="false" width="800px">
      <el-button type="primary" round size="small" @click.native.prevent="addRemark()" style="margin-bottom: 10px;">添加备注</el-button>
      <el-table
        class="list_table"
        :data="remark_data"
        style="width:100%"
        :height="400">
        <el-table-column
          prop="remark"
          label="备注内容"
          min-width="300">
        </el-table-column>
        <el-table-column
          prop="account"
          label="添加人"
          min-width="100">
        </el-table-column>
        <el-table-column
          prop="add_time_txt"
          label="最新记录时间"
          min-width="120">
        </el-table-column>
        <el-table-column
          label="操作"
          width="120">
          <template slot-scope="scope">
            <el-button type="text" size="small" @click.native.prevent="editRemark(scope.$index, remark_data)">编辑</el-button>
            <el-button
              @click.native.prevent="delRemark(scope.$index, remark_data)"
              type="text"
              class="Danger"
              size="small">
              删除
            </el-button>
          </template>
        </el-table-column>
      </el-table>

      <div style="width: 100%;text-align: -webkit-center;padding: 20px 0;">
        <el-footer style="padding: 0;">
          <div v-show="remark_total_page>0" class="page_msg">
            <el-pagination
              background
              layout="prev, pager, next"
              :page-count="remark_total_page"
              :current-page="remark_page"
              @current-change="remark_current_change"
            >
            </el-pagination>
          </div>
        </el-footer>
      </div>
    </el-dialog>


    <el-dialog title="添加备注" :center="true" :visible.sync="addRemarkDialog" :close-on-click-modal="false" width="350px">
      <el-row>
        <el-col :span="24" style="text-align: -webkit-center;">
         <el-input
            type="textarea"
            :rows="6"
            placeholder="请输入内容"
            v-model="remark_val">
          </el-input>
        </el-col>
      </el-row>
        <span slot="footer" class="dialog-footer">
          <el-button type="primary" @click="trueAddRemark()">确 定</el-button>
        </span>
    </el-dialog>

    <el-dialog title="上传附件" :center="true" :visible.sync="uploadFileDialog" :close-on-click-modal="false" width="450px">
      <input  type="file" name="file" ref="tempUploadFile" v-on:change="uploadPic" style="display: none;"/>
      <el-row>
        <el-col :span="24" style="text-align: -webkit-center;">
          <el-tooltip class="item" effect="dark" content="请选择需要上传的文件，大小不超过50M" placement="top">
            <el-button class="true_input" size="mini"  type="primary" @click="clickUse">点击上传文件</el-button>
          </el-tooltip>
        </el-col>
        <el-col :span="24" style="text-align: -webkit-center;padding: 25px;">
          类型支持：EXCEL、PDF、WORD、图片
        </el-col>
      </el-row>
    </el-dialog>


    <el-dialog :center="true" :title="file_title" :visible.sync="lookFileDialog" :close-on-click-modal="false" width="650px">
      <el-button type="primary" round size="small" @click.native.prevent="uploadFileSingle()" style="margin-bottom: 10px;">上传附件</el-button>
      <el-table
        class="list_table"
        :data="file_data"
        style="width:100%"
        :height="400">
        <el-table-column
          prop="file_remark"
          label="文件名称"
          min-width="200">
        </el-table-column>
        <el-table-column
          prop="account"
          label="上传人"
          min-width="100">
        </el-table-column>
        <el-table-column
          prop="add_time_txt"
          label="上传时间"
          min-width="150">
        </el-table-column>
        <el-table-column
          label="操作"
          width="150">
          <template slot-scope="scope">
            <el-button v-if="scope.row.is_image" type="text" size="small" @click.native.prevent="lookImg(scope.$index, file_data)">查看图片</el-button>
            <el-button v-if="!scope.row.is_image" type="text" size="small" @click.native.prevent="downFile(scope.$index, file_data)">下载文件</el-button>
            <el-button
              @click.native.prevent="delFile(scope.$index, file_data)"
              type="text"
              class="Danger"
              size="small">
              删除
            </el-button>
          </template>
        </el-table-column>
      </el-table>

      <div style="width: 100%;text-align: -webkit-center;padding: 20px 0;">
        <el-footer style="padding: 0;">
          <div v-show="total_page>0" class="page_msg">
            <el-pagination
              background
              layout="prev, pager, next"
              :page-count="total_page"
              :current-page="page"
              @current-change="current_change"
            >
            </el-pagination>
          </div>
        </el-footer>
      </div>
    </el-dialog>


  </div>

</template>

<script>
  export default {
    name:'vote_list',
    data() {
      return {
        loading: false,
        lookFileDialog: false,
        uploadFileDialog: false,
        lookRemarkDialog: false,
        addRemarkDialog: false,
        page: 1,
        total_page: 1,
        pagerCount: 10,
        date: '',
        options: [{
          value: 'id',
          label: 'ID'
        }],
        file_title: '附件列表',
        file_data: [],
        search_val: '',
        search_type: 'id',
        template_data: [],
        template_id: '',
        upload_id: '',
        remark: '',
        remark_data: [],
        remark_total_page: 1,
        remark_page: 1,
        diy_id: 0,
        remark_val: '',
        remark_id: 0,
        pigcms_id: 0
      }
    },
    created () {
      var _this = this
      this.template_id = this.$route.query.template_id;
	  if(this.$route.query.pigcms_id){
		  this.pigcms_id = this.$route.query.pigcms_id;
	  }
      this.writeTemplateList();
    },
    methods: {
      delFile(index, rows) {
        let _this = this
        this.$confirm('此操作将永久删除该文件, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          let file_id = rows[index]['file_id'];
          this.delWriteFile(file_id, rows, index, _this);
        }).catch(() => {
          _this.$message({
            type: 'info',
            message: '已取消删除'
          });
        });
      },
      // 删除
      async delWriteFile (file_id, rows, index, _this) {
        let param = {
          file_id: file_id,
        }
        let res = await this.$api.delWriteFile(param);
        console.log(`删除: `, res);
        if (res) {
          rows.splice(index, 1);
          _this.$message({
            type: 'success',
            message: '删除成功!'
          });
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      lookImg(index, rows) {
        let msg = rows[index];
        window.open(msg['file_url_path'], '_blank');
      },
      downFile(index, rows) {
        let msg = rows[index];
        window.open(msg['file_url_path'], '_blank');
      },
      lookRemark(index, rows) {
        let msg = rows[index];
        this.diy_id = msg['id'];
        this.lookRemarkDialog = true;
        this.write_remark_list([]);
      },
      addRemark() {
        this.remark_val = '';
        this.remark_id = 0;
        console.log('addRemark', this.diy_id);
        this.addRemarkDialog=true;
      },
      trueAddRemark() {
        if (!this.remark_val) {
          this.$message({
            message: '请填写备注',
            type: 'warning'
          });
          return false;
        }
        this.add_remark([]);
      },
      editRemark(index, rows) {
        let msg = rows[index];
        console.log('editRemark', msg);
        this.remark_id = msg['remark_id'];
        this.remark_val = msg['remark'];
        this.addRemarkDialog=true;
      },
      delRemark(index, rows) {
        let msg = rows[index];
        console.log('editRemark', msg);
        this.remark_id = msg['remark_id'];
        let _this = this
        this.$confirm('此操作将永久删除该备注, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          this.del_remark([]);
        }).catch(() => {
          _this.$message({
            type: 'info',
            message: '已取消删除'
          });
        });
      },
      // 备注列表
      async write_remark_list(param) {
        param['diy_id'] = this.diy_id;
        param['page'] = this.remark_page;
        let res = await this.$api.write_remark_list(param);
        if (res) {
          this.remark_data = res.list;
          this.remark_total_page = res.total_page;
        }
        console.log('writeFileList', this.file_data);
      },
      // 添加备注
      async add_remark(param) {
        param['diy_id'] = this.diy_id;
        param['remark'] = this.remark_val;
        param['remark_id'] = this.remark_id;
        let res = await this.$api.add_remark(param);
        if (res) {
          this.addRemarkDialog=false;
        } else {
          this.addRemarkDialog=false;
        }
        this.remark_val = '';
        this.remark_id = 0;
        this.write_remark_list([]);
        console.log('writeFileList', this.file_data);
      },
      // 添加备注
      async del_remark(param) {
        param['diy_id'] = this.diy_id;
        param['remark_id'] = this.remark_id;
        let res = await this.$api.del_remark(param);
        if (res) {
          this.addRemarkDialog=false;
        } else {
          this.addRemarkDialog=false;
        }
        this.remark_val = '';
        this.remark_id = 0;
        this.write_remark_list([]);
      },
      remark_current_change(val) {
        this.remark_page = val;
        this.write_remark_list([]);
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
      },
      lookFile(index, rows) {
        let msg = rows[index];
        this.lookFileDialog = true;
        this.file_data = [];
        console.log('lookFile', msg);
        this.file_title = '【' + msg['title'] + '】附件列表';
        let param = {}
        param['diy_id'] = msg['id'];
        this.upload_id = msg['id'];
        this.writeFileList(param)
      },
      lookFileNew() {
        let param = {}
        param['diy_id'] = this.upload_id;
        this.writeFileList(param)
      },
      // 附件列表
      async writeFileList(param) {
        param['page'] = this.page;
        let res = await this.$api.writeFileList(param);
        if (res) {
          this.file_data = res.list;
          this.total_page = res.total_page;
        }
        console.log('writeFileList', this.file_data);
      },
      clickUse() {
        console.log('触发上传图片')
        this.$refs.tempUploadFile.click();
      },
      uploadPic(e) {
        console.log('e', e);
        this.loading = true;
        let _self = this;
        let inputFile = e.target;
        if (!inputFile.files || inputFile.files.length <= 0) {
          return;
        }
        let file_msg = inputFile.files[0];
        console.log('file_msg', file_msg)
        let formData = new FormData()
        formData.append('file', file_msg)
        this.ajaxUploadFile(formData)
      },
      // 上传文件
      async ajaxUploadFile(param) {
        let res = await this.$api.ajaxUploadFile(param);
        if (res) {
          console.log(`ajaxUploadFile: `, res);
          // this.template_img = 'url('+res.file_url+')';
          // this.template_img_val = res.url;
          // this.template_img_box = res.file_url;
          // let that = this;
          if (res['file_id'] && this.upload_id>0) {
            let param1 = {};
            param1['file_id'] = res['file_id'];
            param1['diy_id'] = this.upload_id;
            let res1 = await this.$api.writeAndFile(param1);
            if (res1) {
              this.$message({
                message: '上传成功',
                type: 'success'
              });
              this.lookFileNew();
            }
          }
        }
        this.loading = false;
      },
      uploadFileSingle() {
        this.uploadFileDialog = true;
      },
      uploadFile(index, rows) {
        let msg = rows[index];
        this.uploadFileDialog = true;
        this.upload_id = msg['id'];
        console.log('uploadFile', msg);
      },
      return_vote_list_add: function () {
        this.$router.replace({ path: '/template_list'});
      },
      template_write: function(index, rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/template_write', query: { template_id: msg.template_id }});
      },
      template_write_record: function(index, rows) {
        let msg = rows[index];
        // this.$router.replace({ path: '/vote_statistics', query: { template_id: msg.template_id }});
      },
      // 请求数据
      async writeTemplateList () {
        let _this = this
        let param = {
          page: this.page,
          search_val: this.search_val,
          search_type: this.search_type,
        }
        if (this.template_id) {
           param.template_id = this.template_id;
        }
        if(this.pigcms_id){
          param.pigcms_id = this.pigcms_id;
        }
        if (this.date) {
          let start_time = this.date[0];
          let end_time = this.date[1];
          param.start_time = start_time;
          param.end_time = end_time;
        }
          console.log('param',param);
        let res = await this.$api.writeTemplateList(param);
        if (!res) return;
        console.log('writeTemplateList: ', res);
        this.total_page = res.total_page;
        this.template_data = res.list;
      },
      // 删除
      async delDiyValue (diy_id, rows, index, _this) {
        let param = {
          diy_id: diy_id,
        }
        let res = await this.$api.delDiyValue(param);
        console.log(`删除: `, res);
        if (res) {
          rows.splice(index, 1);
          _this.$message({
            type: 'success',
            message: '删除成功!'
          });
        } else if (res.errorMsg) {
          _this.$message({
            type: 'info',
            message: res.errorMsg
          });
        }
        return res;
      },
      search_list() {
        console.log('搜索');
        console.log('search_type',this.search_type);
        console.log('search_val',this.search_val);
        this.page = 1;
        this.writeTemplateList();
      },
      current_change(val) {
        this.page = val;
        this.writeTemplateList();
        console.log(`当前页: ${val}`);
        console.log(`当前页1: `,this.page);
      },
      tableRowClassName({row, rowIndex}) {
        if (row['status'] === '0') {
          return 'warning_row';
        }
        return '';
      },
      deleteRow(index, rows) {
        let _this = this
        this.$confirm('此操作将永久删除该填写内容, 是否继续?', '提示', {
          confirmButtonText: '确定',
          cancelButtonText: '取消',
          type: 'warning'
        }).then(() => {
          let diy_id = rows[index]['id'];
          this.delDiyValue(diy_id, rows, index, _this);
        }).catch(() => {
          _this.$message({
            type: 'info',
            message: '已取消删除'
          });
        });
      },
      editRow(index,rows) {
        let msg = rows[index];
        this.$router.replace({ path: '/template_write', query: { diy_id: msg.id , 'paths': 'write_list'}});
      },
      add_write() {
        this.$router.replace({ path: '/template_write', query: { template_id: this.template_id, 'paths': 'write_list' }});
      }
    }
  }
</script>
<style scoped>
  .write_list_box {
    padding: 64px 10px;
  }
  .write_list_box .list_top {
    width: 100%;
    padding: 15px;
    text-align: left;
    font-size: 14px;
    box-shadow: 0 2px 12px 0 rgba(0, 0, 0, 0.1);
    background: #ffffff;
    position: fixed;
    top: 0;
    z-index: 999;
  }
  .write_list_box .list_table {
    border: 1px solid #EBEEF5;
  }
  .write_list_box .table_box {
    width: 100%;
  }
  .write_list_box .Danger {
    color: #F56C6C;
  }
  .write_list_box .search_width {
    width: 150px;
  }
  .write_list_box .page_msg {
    text-align: center;
  }
</style>
